# area: paramspec_concatenate
# hypothesis: a ParamSpec decorator factory must keep the wrapped function's defaults and keyword-only parameters, and a method decorated with it must keep self bound and checked.
from collections.abc import Callable
from typing import reveal_type


def repeat[**P, R](times: int) -> Callable[[Callable[P, R]], Callable[P, list[R]]]:
    def deco(fn: Callable[P, R]) -> Callable[P, list[R]]:
        def inner(*args: P.args, **kwargs: P.kwargs) -> list[R]:
            return [fn(*args, **kwargs) for _ in range(times)]
        return inner
    return deco


@repeat(2)
def greet(name: str, *, punct: str = '!') -> str:
    return name + punct


class Counter:
    def __init__(self, start: int) -> None:
        self.value = start

    @repeat(3)
    def bump(self, step: int = 1) -> int:
        self.value += step
        return self.value


reveal_type(greet)
reveal_type(Counter.bump)
reveal_type(Counter(0).bump)
print(greet('a', punct='?'), Counter(0).bump(2))
try:
    greet(1)  # expect-error: int is not str
except TypeError as exc:
    print('runtime:', type(exc).__name__)
try:
    Counter(0).bump(step='x', extra=1)  # expect-error
except TypeError as exc:
    print('runtime:', type(exc).__name__)
